import pathlib,tempfile,subprocess
root=pathlib.Path(__file__).resolve().parent
with tempfile.TemporaryDirectory() as tmp:
 t=pathlib.Path(tmp);p=t/'RegionTest.java';p.write_text('''import java.util.*;import java.util.function.LongPredicate;import org.sonicraft.backport.Region47;
public class RegionTest {static void eq(int x,int e){if(x!=e)throw new AssertionError(x+" != "+e);}public static void main(String[] a){Set<Long> claims=new HashSet<>();claims.add(Region47.key(0,0));LongPredicate land=k->{int x=(int)(k>>32),z=(int)(long)k;return z>=0&&z<5&&((x>=0&&x<5)||(x>=7&&x<12));};eq(Region47.connected(Region47.key(4,4),claims,land,8192,new HashSet<>()),1);eq(Region47.connected(Region47.key(8,3),claims,land,8192,new HashSet<>()),0);eq(Region47.connected(Region47.key(-2,-2),claims,k->true,2,new HashSet<>()),-1);claims.add(Region47.key(10,4));eq(Region47.connected(Region47.key(8,3),claims,land,8192,new HashSet<>()),1);Set<Long> diagonal=new HashSet<>();diagonal.add(Region47.key(0,0));eq(Region47.connected(Region47.key(1,1),diagonal,k->k==Region47.key(1,1)||k==Region47.key(0,0),20,new HashSet<>()),0);if(Region47.key(-1,0)==Region47.key(0,-1))throw new AssertionError();System.out.println("PASS: same region denied; separate biome island allowed; second claim; bounded scan; negative coordinates; diagonal islands");}}''')
 subprocess.run(['javac','-d',tmp,str(root/'src/org/sonicraft/backport/Region47.java'),str(p)],check=True);subprocess.run(['java','-cp',tmp,'RegionTest'],check=True)
